  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/images/pathfinder/wiki/ialt.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/images/pathfinder/wiki/ibase.png&#39;;&quot; /&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Guide du ma&#238;tre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Gamemastery Guide/Guide du ma&#238;tre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoGDM.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Quand vous introduisez une apparition, vous estompez la limite entre les &lt;a class=&quot;pagelink&quot; href=&quot;Pi&#232;ges.html&quot; title=&quot;Les pi&#232;ges&quot;&gt;pi&#232;ges&lt;/a&gt; et les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;morts-vivants&lt;/a&gt;, car il s’agit d’une r&#233;gion dangereuse cr&#233;&#233;e par des esprits sans repos qui r&#233;agissent violemment &#224; la pr&#233;sence des vivants. Les conditions de cr&#233;ation de l’apparition varient au cas par cas, mais elles d&#233;coulent toutes d’une source d’angoisse terrifiante, d’origine physique ou mentale, v&#233;cue par une cr&#233;ature vivante tortur&#233;e. Une unique source de souffrances peut donner naissance &#224; plusieurs apparitions et des sources diverses peuvent s’unir pour cr&#233;er une seule apparition. Le pouvoir relatif de la source influe bien peu sur la puissance de l’apparition, c’est l’ampleur de la souffrance ou du d&#233;sespoir &#224; l’origine de l’apparition qui d&#233;termine sa force. Souvent les r&#233;gions hant&#233;es sont habit&#233;es par des morts‑vivants, il se peut m&#234;me qu’une personne d&#233;c&#233;d&#233;e se rel&#232;ve en tant que fant&#244;me (ou autre mort‑vivant) et qu’elle soit &#224; l’origine de nombreuses apparitions.&lt;br /&gt;&lt;br /&gt;Ces derni&#232;res impr&#232;gnent une zone sp&#233;cifique et il existe souvent de nombreuses zones d’apparitions dans une m&#234;me structure. Une maison hant&#233;e classique n’abrite pas une unique apparition, en r&#232;gle g&#233;n&#233;rale, la b&#226;tisse comporte une douzaine de pi&#232;ces avec des apparitions.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Les r&#232;gles des apparitions&lt;a class=&quot;headeranchor&quot; id=&quot;Les_r&#232;gles_des_apparitions_0&quot; href=&quot;#Les_r&#232;gles_des_apparitions_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;div style=&quot;float:right; margin:8px 6px 0px 10px&quot;&gt;&lt;b&gt;&lt;i&gt;Voir des &lt;a class=&quot;pagelink&quot; href=&quot;Exemples-Dapparitions.html&quot; title=&quot;Exemples d&amp;#39;apparitions&quot;&gt;exemples d&#39;apparitions&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/div&gt;M&#234;me si les apparitions fonctionnent comme des &lt;a class=&quot;pagelink&quot; href=&quot;Pi&#232;ges.html&quot; title=&quot;Les pi&#232;ges&quot;&gt;pi&#232;ges&lt;/a&gt;, elles sont plus difficiles &#224; d&#233;tecter, car on ne peut pas les observer avant le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; pendant lequel elles se manifestent. Des sorts comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Des-Morts-Vivants.html&quot; title=&quot;D&#233;tection des morts-vivants&quot;&gt;d&#233;tection des morts-vivants&lt;/a&gt;&lt;/i&gt; ou &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Mal.html&quot; title=&quot;D&#233;tection du Mal&quot;&gt;d&#233;tection de l’alignement&lt;/a&gt;&lt;/i&gt; de type appropri&#233; donnent une chance de remarquer l’apparition avant qu’elle ne se mat&#233;rialise (ce qui permet au personnage de faire un test adapt&#233; pour la d&#233;celer, mais avec un malus de –4).&lt;br /&gt;&lt;br /&gt;L’apparition hante une zone maximale de 1,50 m&#232;tre de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Rayon.html&quot; title=&quot;rayon&quot;&gt;rayon&lt;/a&gt; (1 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) par point de &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; mais en g&#233;n&#233;ral, elle se limite &#224; la pi&#232;ce qu’elle occupe.&lt;br /&gt;&lt;br /&gt;Quand une apparition se mat&#233;rialise, elle se manifeste avec une &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat#Initiative.html&quot; title=&quot;initiative&quot;&gt;initiative&lt;/a&gt; de 10 lors d’un &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat.html#ROUNDSURPRISE&quot; title=&quot;Le d&#233;roulement d&amp;#39;un combat&quot;&gt;round de surprise&lt;/a&gt;. Tous les personnages qui se trouvent &#224; proximit&#233; peuvent tenter de la rep&#233;rer au d&#233;but de ce round &#224; l’aide d’un test de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;. Toutes les apparitions d&#233;tectent les sources de vie et se d&#233;clenchent au contact ou en pr&#233;sence de cr&#233;atures vivantes, m&#234;me si certaines se laissent tromper par des effets de type &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;-Pour-Les-Morts-Vivants.html&quot; title=&quot;Invisibilit&#233; pour les morts-vivants&quot;&gt;invisibilit&#233; pour les morts-vivants&lt;/a&gt;&lt;/i&gt; ou &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;Au cours du &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat.html#ROUNDSURPRISE&quot; title=&quot;Le d&#233;roulement d&amp;#39;un combat&quot;&gt;round de surprise&lt;/a&gt; pendant lequel l’apparition se manifeste, toute &#233;nergie positive appliqu&#233;e &#224; l’apparition (par une &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre#Canalisationdenergie.html&quot; title=&quot;canalisation&quot;&gt;canalisation&lt;/a&gt;, un sort de soin ou autre) peut entamer ses points de vie (l’apparition n’a pas droit &#224; un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour att&#233;nuer les d&#233;g&#226;ts de ces effets et toute attaque qui n&#233;cessite un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d’attaque&lt;/a&gt; doit franchir une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; de 10 pour toucher l’apparition et pas seulement la structure qu’elle occupe). &#192; moins que l’apparition ne poss&#232;de une faiblesse inhabituelle, les autres formes d’attaque ne peuvent pas r&#233;duire ses points de vie.&lt;br /&gt;&lt;br /&gt;Si l’apparition tombe &#224; 0 &lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;pv&quot;&gt;point de vie&lt;/a&gt; gr&#226;ce &#224; l’&#233;nergie positive, elle est neutralis&#233;e ; si cela se produit lors du round de surprise avant qu’elle n’agisse (avec son initiative de 10), elle n’a aucun effet.&lt;br /&gt;&lt;br /&gt;Une apparition peut virtuellement reproduire n’importe quel effet de sort existant, mais souvent avec des caract&#233;ristiques physiques et sensorielles diff&#233;rentes de celles du sort (et bien plus inqui&#233;tantes ou terrifiantes). (On peut tout &#224; fait cr&#233;er une apparition dont les effets ne correspondent pas &#224; un sort existant, mais il faut alors d&#233;finir un nouvel effet de sort.) Une apparition peut noyer une pi&#232;ce dans les flammes (et reproduire un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Boule-De-Feu.html&quot; title=&quot;Boule de feu&quot;&gt;boule de feu&lt;/a&gt;&lt;/i&gt; ou de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp&#234;te-De-Feu.html&quot; title=&quot;Temp&#234;te de feu&quot;&gt;temp&#234;te de feu&lt;/a&gt;&lt;/i&gt;), impr&#233;gner une salle d’un sentiment de terreur (et imiter un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Frayeur.html&quot; title=&quot;Frayeur&quot;&gt;frayeur&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Effroi.html&quot; title=&quot;Effroi&quot;&gt;effroi&lt;/a&gt;&lt;/i&gt; ou &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Terreur.html&quot; title=&quot;Terreur&quot;&gt;terreur&lt;/a&gt;&lt;/i&gt;) ou essayer de faire mourir la cible de &lt;a class=&quot;pagelink&quot; href=&quot;Terreur-(Capacit&#233;).html&quot; title=&quot;peur&quot;&gt;peur&lt;/a&gt; (comme un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Assassin-Imaginaire.html&quot; title=&quot;Assassin imaginaire&quot;&gt;assassin imaginaire&lt;/a&gt;&lt;/i&gt;). &#192; vous de d&#233;terminer comment l’apparition se manifeste.&lt;br /&gt;&lt;br /&gt;Une apparition neutralis&#233;e n’est pas d&#233;truite pour autant et peut se mat&#233;rialiser &#224; nouveau au bout d’un certain temps. Pour la d&#233;truire d&#233;finitivement, il faut entreprendre une certaine action comme de br&#251;ler la maison hant&#233;e jusqu’aux fondations ou d’enterrer les os de l’esclave qui mourut sur les lieux et se trouve &#224; l’origine des apparitions. Cet acte est sp&#233;cifique &#224; chaque cas, m&#234;me si des apparitions voisines partagent souvent la m&#234;me condition de destruction.&lt;br /&gt;&lt;br /&gt;Certaines apparitions persistent et leurs effets imm&#233;diats se prolongent au‑del&#224; du &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat.html#ROUNDSURPRISE&quot; title=&quot;Le d&#233;roulement d&amp;#39;un combat&quot;&gt;round de surprise&lt;/a&gt; lors de rounds entiers. Ces apparitions continuent d’utiliser leurs effets une fois par &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;, &#224; leur &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat#Initiative.html&quot; title=&quot;initiative&quot;&gt;initiative&lt;/a&gt;, jusqu’&#224; ce qu’on les d&#233;truise ou qu’elles n’aient plus de cible.&lt;br /&gt;&lt;br /&gt;Toute apparition produit un effet &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;mental&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;peur&lt;/a&gt; lors du &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat.html#ROUNDSURPRISE&quot; title=&quot;Le d&#233;roulement d&amp;#39;un combat&quot;&gt;round de surprise&lt;/a&gt;, m&#234;me si elle a &#233;galement un effet physique. L’immunit&#233; contre la peur immunise aussi contre les effets directs de l’apparition, mais pas contre les effets secondaires qui r&#233;sultent de ses attaques.&lt;br /&gt;&lt;br /&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les &#233;l&#233;ments des apparitions&lt;a class=&quot;headeranchor&quot; id=&quot;Les_&#233;l&#233;ments_des_apparitions_1&quot; href=&quot;#Les_&#233;l&#233;ments_des_apparitions_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les apparitions se pr&#233;sentent selon le profil suivant :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Nom de l’apparition.&lt;/b&gt; Le nom de l’apparition est suivi de son &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;PX.&lt;/b&gt; Nombre de points d’exp&#233;rience &#224; accorder aux PJ pour avoir surv&#233;cu &#224; l’apparition, en fonction de son &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Alignement et zone.&lt;/b&gt; Cette ligne indique l’alignement de l’apparition et les dimensions de la zone qu’elle hante (jusqu’&#224; 1,50 m&#232;tre (1 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) par FP). S’il s’agit d’une apparition persistante, cette information est donn&#233;e ici.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Niveau de lanceur de sorts.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;Niveau de lanceur de sorts&lt;/a&gt; effectif de l’apparition pour d&#233;terminer l’efficacit&#233; d’une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dissipation-De-La-Magie.html&quot; title=&quot;Dissipation de la magie&quot;&gt;dissipation de la magie&lt;/a&gt;&lt;/i&gt; et les r&#233;sultats des effets de sorts cr&#233;&#233;s.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Rep&#233;rage.&lt;/b&gt; Indique le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Jettest.html&quot; title=&quot;test&quot;&gt;test&lt;/a&gt; de comp&#233;tence et le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; requis pour remarquer l’apparition pendant le &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat.html#ROUNDSURPRISE&quot; title=&quot;Le d&#233;roulement d&amp;#39;un combat&quot;&gt;round de surprise&lt;/a&gt;, avant qu’elle ne se manifeste. La l&#233;g&#232;re information sensorielle qui r&#233;sulte d’un test r&#233;ussi (comme un faible g&#233;missement fantomatique, une odeur de chair br&#251;l&#233;e ou du sang frais qui suinte des murs) est indiqu&#233;e entre parenth&#232;ses, apr&#232;s le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;pv.&lt;/b&gt; Nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;pv&quot;&gt;points de vie&lt;/a&gt; effectifs de l’apparition, pour d&#233;terminer les d&#233;g&#226;ts caus&#233;s par l’&#233;nergie positive. Les points de vie de l’apparition sont &#233;gaux au double de son FP, sauf dans le cas d’apparitions persistantes, auquel cas ils sont &#233;gaux &#224; 4,5 x FP (arrondi &#224; l’inf&#233;rieur).&lt;/li&gt;&lt;li&gt;&lt;b&gt;Faiblesses.&lt;/b&gt; Indique toute faiblesse &#233;ventuelle de l’apparition, comme celles qui se laissent leurrer par des effets comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;-Pour-Les-Morts-Vivants.html&quot; title=&quot;Invisibilit&#233; pour les morts-vivants&quot;&gt;invisibilit&#233; pour les morts-vivants&lt;/a&gt;&lt;/i&gt; ou celles sensibles aux d&#233;g&#226;ts issus d’autres sources que l’&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre#Canalisationdenergie.html&quot; title=&quot;canalisation&quot;&gt;&#233;nergie positive&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;D&#233;clencheur.&lt;/b&gt; Les conditions qui provoquent l’apparition. Les apparitions de proximit&#233; se mat&#233;rialisent quand une cr&#233;ature entre dans la zone hant&#233;e. Une apparition de contact n’est active que lorsque quelqu’un touche un objet ou un endroit pr&#233;cis de la zone, mais elle per&#231;oit (et peut donc viser) n’importe quelle cr&#233;ature pr&#233;sente.&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;initialisation.&lt;/b&gt; P&#233;riode qui doit s’&#233;couler avant que l’apparition ne tente de revenir. &#192; moins d’&#234;tre d&#233;truite, une apparition tente de se r&#233;initialiser &#224; l’issue de cette dur&#233;e gr&#226;ce &#224; un test de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 10. En cas d’&#233;chec, elle doit attendre de nouveau que cette dur&#233;e s’&#233;coule avant de faire un nouvel essai.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Effet.&lt;/b&gt; D&#233;taille les effets exacts de l’apparition, y compris la mani&#232;re dont elle se manifeste.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Destruction.&lt;/b&gt; D&#233;crit l’acte &#224; accomplir pour d&#233;truire d&#233;finitivement l’apparition.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Cr&#233;er une apparition&lt;a class=&quot;headeranchor&quot; id=&quot;Cr&#233;er_une_apparition_2&quot; href=&quot;#Cr&#233;er_une_apparition_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 16px 16px&quot;&gt;
&lt;div style=&quot;border: 1px solid #4b3124; padding: 4px&quot;&gt;
&lt;center&gt;
&lt;table CLASS=&quot;tablo&quot;&gt;&lt;caption&gt;Modificateurs de FP des apparitions&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Type&lt;/td&gt;&lt;td&gt;Modificateur au FP&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Persistante&lt;/td&gt;&lt;td&gt;+2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;DD de r&#233;p&#233;rage&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;15 ou moins&lt;/td&gt;&lt;td&gt;‑1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;16-20&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;21-25&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;26-29&lt;/td&gt;&lt;td&gt;+2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;30 ou plus&lt;/td&gt;&lt;td&gt;+3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;D&#233;lai de r&#233;initialisation&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;1 minute&lt;/td&gt;&lt;td&gt;+2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;1 heure&lt;/td&gt;&lt;td&gt;+1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;1 jour&lt;/td&gt;&lt;td&gt;+0&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;1 semaine&lt;/td&gt;&lt;td&gt;‑1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Exemple de faiblesses&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Lent (se manifeste avec une initiative de 0)&lt;/td&gt;&lt;td&gt;‑2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Sensible &#224; un type de d&#233;g&#226;ts suppl&#233;mentaire&lt;/td&gt;&lt;td&gt;‑1 par type&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Leurr&#233; par &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;-Pour-Les-Morts-Vivants.html&quot; title=&quot;Invisibilit&#233; pour les morts-vivants&quot;&gt;invisibilit&#233; pour les morts-vivants&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;‑2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Leurr&#233; par &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;‑1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Leurr&#233; par la &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;‑3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;Se d&#233;clenche par contact&lt;/td&gt;&lt;td&gt;‑2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td CLASS=&quot;note&quot; COLSPAN=&quot;2&quot;&gt;* L’apparition fait un test de niveau de lanceur de sorts au lieu d’un&lt;br /&gt; test de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; quand elle tente de rep&#233;rer quelqu’un qui use&lt;br /&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;/div&gt;&lt;/div&gt;&lt;br /&gt;Voici les &#233;tapes &#224; suivre pour cr&#233;er une apparition comme celle donn&#233;e dans l’exemple ci‑contre.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;tape 1 : D&#233;terminer le FP de base.&lt;/b&gt; Le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; de base de l’apparition est &#233;gal &#224; 1 + niveau des sorts imit&#233;s.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;tape 2 : D&#233;terminer le FP r&#233;el.&lt;/b&gt; Choisissez les &#233;l&#233;ments que vous voulez int&#233;grer &#224; votre apparition et ajoutez‑les au FP de base pour obtenir le FP final (Voir la table &#224; droite).&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;tape 3 : D&#233;terminer le niveau de lanceur de sorts.&lt;/b&gt; Le niveau de lanceur de sorts de l’apparition est &#233;gal &#224; son FP r&#233;el.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;tape 4 : D&#233;terminer les points de vie .&lt;/b&gt; Les points de vie de l’apparition sont &#233;gaux au double de son FP (ou &#224; FP x 4,5 pour une apparition persistante).&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;tape 5 : Calculer les attaques et le DD des jets de sauvegarde.&lt;/b&gt; Le modificateur d’attaque de l’apparition (s’il en faut un) est &#233;gal &#224; son FP. Si le sort de l’apparition autorise un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; pour r&#233;sister &#224; ses effets ou les annuler, le DD de ce jet est &#233;gal &#224; 10 + niveau du sort + modificateur de la valeur minimum de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques.html&quot; title=&quot;caract&#233;ristique&quot;&gt;caract&#233;ristique&lt;/a&gt; n&#233;cessaire pour lancer un sort de ce niveau.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Murs qui saignent&lt;div style=&quot;float:right;&quot;&gt;FP 5&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;PX 1 600&lt;/li&gt;&lt;li&gt;&lt;b&gt;Apparition&lt;/b&gt; (couloir de 1,50 m&#232;tre (1 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) sur 6 m&#232;tres), CM&lt;/li&gt;&lt;li&gt;&lt;b&gt;Niveau de lanceur de sorts&lt;/b&gt; 5&lt;/li&gt;&lt;li&gt;&lt;b&gt;Rep&#233;rage&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; DD 20 (pour entendre des pleurs &#233;touff&#233;s)&lt;/li&gt;&lt;li&gt;&lt;b&gt;pv&lt;/b&gt; 10 ; &lt;b&gt;D&#233;clencheur&lt;/b&gt; proximit&#233; ; &lt;b&gt;R&#233;initialisation&lt;/b&gt; 1 jour&lt;/li&gt;&lt;li&gt;&lt;b&gt;Effet&lt;/b&gt; Quand cette apparition se mat&#233;rialise, d’&#233;pais filets de sang coulent le long des murs, accompagn&#233;s des hurlements aigus d’une femme. Toutes les cr&#233;atures qui se trouvent dans le couloir sont vis&#233;es par un sort de &lt;a class=&quot;pagelink&quot; href=&quot;Terreur.html&quot; title=&quot;Terreur&quot;&gt;terreur&lt;/a&gt; (jet de sauvegarde DD 16).&lt;/li&gt;&lt;li&gt;&lt;b&gt;Destruction&lt;/b&gt; Il faut d&#233;gager le cadavre de la jeune fille emmur&#233;e derri&#232;re le couloir et lui donner des fun&#233;railles d&#233;centes.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;
